Tool response:
Tool: record_eligibility_check
Description: Record Eligibility Check
Parameters:
    {
      "type": "object",
      "properties": {
        "patient_id": {
          "type": "integer",
          "title": "Patient Id"
        },
        "appointment_id": {
          "type": "integer",
          "title": "Appointment Id"
        },
        "patient_insurance_id": {
          "type": "integer",
          "title": "Patient Insurance Id"
        },
        "checked_by_user_id": {
          "type": "integer",
          "title": "Checked By User Id"
        },
        "check_date": {
          "type": "string",
          "title": "Check Date"
        },
        "response": {
          "type": "string",
          "pattern": "^(eligible|ineligible|pending|error)$",
          "title": "Response"
        },
        "response_details": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Response Details"
        }
      },
      "required": [
        "patient_id",
        "appointment_id",
        "patient_insurance_id",
        "checked_by_user_id",
        "check_date",
        "response"
      ]
    }

